import {useState} from "react"
import React from "react"

const   WorkoutForm =()=>{
    const [title, settitle ]=useState('');
    const [sets, setsets]=useState('');
    const [reps, setreps]=useState('');
    const [weight,setweight]=useState('');
    const [dropsets,setdropsets]=useState(false);
    const [error,seterror]=useState(null);

    const handlesubmit = async (e)=>{
        e.preventDefault();//to prevent the page from refreshing when the form is submitted 
        const workouts={title,sets,reps,weight,dropsets};
        const response=await fetch('/api/workouts',{
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify(workouts)

        })
        const json=await response.json();
        if(!response.ok){
            seterror(json.error);
        }
        if(response.ok){
            settitle('');
            setsets('');
            setreps('');
            setweight('');
            setdropsets(false);
            seterror(null);
            console.log('New workout added',json);
        }

    }

    return(
        <form className="create" onSubmit={handlesubmit}>
            <h3> Add a new Workout</h3>
            <lablel>exercise</lablel>
            <input type="text" onChange={(e)=>settitle(e.target.value)} value={title}/>
            <lablel>sets</lablel>
            <input type="number" onchange={(e)=>settitle(e.target.value)} value={sets}/>
            <lablel>reps</lablel>
            <input type="number" onchange={(e)=>settitle(e.target.value)} value={reps}/>
            <lablel> weights(Kg) </lablel>
            <input type="number" onchange={(e)=>settitle(e.target.value)} value={weight}/>
            <lablel>dropSets</lablel>
            <input type="Boolean" onchange={(e)=>settitle(e.target.value)} value={dropsets}/>

            <button className="addworkout"> add workout </button>
        </form>

    )
   

}

export default WorkoutForm;
